/**
 * Application icons, generated by scripts/icons.ts.
 *
 * Base64 rather than files on disk: the runtime serves them from memory and
 * the container image needs no assets directory. Regenerate with
 * `npx tsx scripts/icons.ts` after changing the mark.
 */

/** 192x192, 9619 bytes. */
export const icon192 = Buffer.from('', 'base64');

/** 512x512, 24951 bytes. */
export const icon512 = Buffer.from('', 'base64');

/** 512x512, 34540 bytes. */
export const maskable512 = Buffer.from('', 'base64');

/** 180x180, 9040 bytes. */
export const appleTouch180 = Buffer.from('', 'base64');

/** 64x64, 3023 bytes. */
export const favicon64 = Buffer.from('', 'base64');
